import forge.ai.*;
import forge.ai.bridge.*;
import forge.deck.Deck;
import forge.game.*;
import forge.game.card.*;
import forge.game.player.*;
import forge.game.phase.*;
import forge.game.zone.*;
import com.google.gson.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;

/** Actual command-zone payment, selected colors, commander tax and pain damage. */
public class SelectedManaReplayRegression extends AITest {
 static JsonObject activate(Card card,String color){var ability=card.getManaAbilities().stream().filter(a->a.getParam("Produced").startsWith("Combo ")).findFirst().orElseThrow();JsonObject step=new JsonObject();step.addProperty("op","activate_basic");step.addProperty("card_id",card.getId());step.addProperty("card_name",card.getName());JsonObject params=new JsonObject();ability.getMapParams().forEach(params::addProperty);step.add("parameters",params);JsonObject choice=new JsonObject();choice.addProperty("hook","forge/ai/PlayerControllerAi.chooseColor(Ljava/lang/String;Lforge/game/spellability/SpellAbility;Lforge/card/ColorSet;)B");choice.addProperty("title","Select Mana to Produce");choice.addProperty("offered",color);choice.addProperty("selected_color",color);choice.addProperty("selected_mask",forge.card.MagicColor.fromName(color));step.add("color_choice",choice);return step;}
 static JsonObject spend(Card card,String color){JsonObject step=new JsonObject(),unit=new JsonObject();step.addProperty("op","spend");unit.addProperty("color",color);unit.addProperty("source_card_id",card.getId());unit.addProperty("snow",false);unit.addProperty("restricted",false);step.add("mana",unit);return step;}
 public static void main(String[] args)throws Exception{
  String mode=args[0];boolean tax=mode.equals("tax");Path root=Path.of(args[1]);Files.createDirectories(root);System.setProperty("forge.audit.directory",root.resolve("audit").toString());SelectedManaReplayRegression test=new SelectedManaReplayRegression();test.initializeModel();test.initAndCreateGame();List<RegisteredPlayer> seats=new ArrayList<>();for(int i=0;i<4;i++)seats.add(new RegisteredPlayer(new Deck()).setPlayer(new LobbyPlayerAi("seat"+i,null)));GameRules rules=new GameRules(GameType.Commander);rules.addAppliedVariant(GameType.Commander);Game game=new Game(seats,rules,new Match(rules,seats,"Selected mana"));Player p=game.getPlayers().get(0);for(Player seat:game.getPlayers())test.fillLibrary(seat,10);game.setAge(GameStage.Play);game.getPhaseHandler().devModeSet(PhaseType.MAIN1,p,false);game.getPhaseHandler().setPriority(p);
  Card tower=test.addCardToZone("Command Tower",p,ZoneType.Battlefield),pain=test.addCardToZone("Brushland",p,ZoneType.Battlefield),ring=test.addCardToZone("Sol Ring",p,ZoneType.Battlefield),card=test.addCardToZone("Frodo, Adventurous Hobbit",p,ZoneType.Command);p.addCommander(card);p.initCommanderColor(card);if(tax)p.incCommanderCast(card);game.getAction().checkStaticAbilities();var spell=card.getFirstSpellAbility().copy();spell.setActivatingPlayer(p);spell.setMayPlay(card.mayPlay(p).get(0));int life=p.getLife();
  JsonObject row=new JsonObject();row.addProperty("kind","decision");row.addProperty("index",0);row.addProperty("actor_id",p.getId());row.addProperty("hook","forge/game/player/PlayerController.payManaCost(Lforge/game/cost/CostPartMana;Lforge/game/spellability/SpellAbility;Ljava/lang/String;Lforge/game/mana/ManaConversionMatrix;Z)Z");row.addProperty("decision_type","selected_tap_mana");row.addProperty("component","{W}{B}");row.addProperty("commander",true);row.addProperty("prior_commander_casts",tax?1:0);row.addProperty("commander_tax",tax?2:0);row.addProperty("source_ability",card.getId()+":"+spell.getId());row.addProperty("ability_api","PermanentCreature");JsonArray ops=new JsonArray();ops.add(activate(tower,mode.equals("wrong-color")?"U":"B"));ops.add(spend(tower,"B"));ops.add(activate(pain,"W"));ops.add(spend(pain,"W"));if(tax){JsonObject step=new JsonObject();step.addProperty("op","activate_basic");step.addProperty("card_id",ring.getId());step.addProperty("card_name",ring.getName());JsonObject params=new JsonObject();ring.getManaAbilities().get(0).getMapParams().forEach(params::addProperty);step.add("parameters",params);ops.add(step);ops.add(spend(ring,"C"));ops.add(spend(ring,"C"));}row.add("operations",ops);
  if(tax)row.addProperty("component","{2}{W}{B}");
  Path tape=root.resolve("decisions.jsonl");Files.writeString(tape,row+"\n{\"kind\":\"decision_tape_complete\",\"decisions\":1}\n",StandardOpenOption.CREATE_NEW);System.setProperty("forge.decision.replayTape",tape.toString());System.setProperty("forge.decision.replaySha256",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(tape))));System.setProperty("forge.decision.replayDiagnostics",root.resolve("diagnostics").toString());DurableEvidence.begin("selected-mana-fixture");EngineEvidence.begin(game);
  try{if(!ComputerUtil.handlePlayingSpellAbility(p,spell,null))throw new AssertionError("Cast failed");if(mode.equals("wrong-color"))throw new AssertionError("Illegal color accepted");var actual=game.getStack().peekAbility();if(actual.getPayingMana().size()!=(tax?4:2)||p.getLife()!=life-1||!tower.isTapped()||!pain.isTapped()||!p.getManaPool().isEmpty()||!card.isInZone(ZoneType.Stack))throw new AssertionError("Actual payment/tax/damage diverged");DecisionReplay.finish();EngineEvidence.finish();System.out.println("PASS four-player "+mode+": command-zone payment; actual color production; Brushland1 damage; tax paid from actual units");}
  catch(IllegalStateException error){if(!mode.equals("wrong-color"))throw error;if(!error.getMessage().contains("production color"))throw error;if(tower.isTapped()||pain.isTapped()||p.getLife()!=life)throw new AssertionError("Invalid choice mutated mana source or life");System.out.println("PASS four-player illegal Command Tower color rejected before tap/damage");}
  if(!mode.equals("wrong-color")){JsonObject result=new JsonObject();result.addProperty("seed",97);result.addProperty("status","completed");DurableEvidence.finish(root.resolve("results"),97,"fixture\nDragonMind Result: "+result+"\n",result);System.out.println("SEALED targeted fixture; not a complete Commander game");}System.exit(0);
 }
}
